const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const paths={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',heart:'<path d="M20.8 4.6a5.4 5.4 0 0 0-7.6 0L12 5.8l-1.2-1.2a5.4 5.4 0 0 0-7.6 7.6L12 21l8.8-8.8a5.4 5.4 0 0 0 0-7.6Z"/>',bag:'<path d="M5 7h14l2 15H3L5 7Z"/><path d="M8 9V6a4 4 0 0 1 8 0v3"/>',gift:'<path d="M3 10h18v4H3zM5 14v8h14v-8M12 10v12"/><path d="M12 10C2 10 5 0 9 4l3 6Zm0 0c10 0 7-10 3-6l-3 6Z"/>',return:'<path d="M4 10a8 8 0 1 1 1 9M4 4v6h6M9 14l2 2 5-5"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',support:'<path d="M4 15v-3a8 8 0 0 1 16 0v6a4 4 0 0 1-4 4h-4M4 11H2v7h4v-7H4Zm16 0h2v7h-4v-7h2Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.gift}</svg>`;
$$('[data-icon]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)));
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function saved(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let cart=saved('callie-cart',[]),wishes=saved('callie-wishes',[]),currentCategory='Best Sellers',currentSearch='',limit=10,bannerIndex=0,toastTimer;
const persist=()=>{localStorage.setItem('callie-cart',JSON.stringify(cart));localStorage.setItem('callie-wishes',JSON.stringify(wishes));$('#bag-count').textContent=cart.reduce((n,p)=>n+p.qty,0);$('#wish-count').textContent=wishes.length||''};
const money=n=>'$'+n.toFixed(2);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
$('#logo').src=DATA.logo;$('.footer-logo').src=DATA.logo;
function showBanner(i){bannerIndex=(i+DATA.banners.length)%DATA.banners.length;const b=DATA.banners[bannerIndex];$('#hero-image').src=b.image;$('#hero-image').alt=b.name+' — personalized gifts';$('#hero-mobile').srcset=b.mobile;$('#hero-dots').innerHTML=DATA.banners.map((_,j)=>`<button aria-label="Show ${escapeHTML(DATA.banners[j].name)} banner" class="${j===bannerIndex?'active':''}" data-slide="${j}"></button>`).join('')}
showBanner(0);$('#hero-prev').onclick=()=>showBanner(bannerIndex-1);$('#hero-next').onclick=()=>showBanner(bannerIndex+1);$('#hero-dots').onclick=e=>{if(e.target.dataset.slide)showBanner(+e.target.dataset.slide)};$('#hero-link').onclick=()=>browse(DATA.banners[bannerIndex].name);
$('#categories').innerHTML=DATA.categories.map(c=>`<button class="category" data-category="${escapeHTML(c.name)}"><span class="category-img"><img src="${c.image}" alt="${escapeHTML(c.name)}" loading="lazy"></span><span>${escapeHTML(c.name)}</span></button>`).join('');
const matches={Christmas:/christmas|snowman|santa|ornament|scarf|winter/i,'Tote Bag':/bag|tote/i,Blankets:/blanket/i,'Custom Blankets':/blanket/i,'Birthstone Rings':/birth|flower|jewel|bracelet/i,Pajamas:/pajama|pants/i,'Photo Bracelet':/photo|bracelet/i,'Night Lights':/light/i,'For Kids':/kid|girl|boy|child/i,'For Her':/women|woman|flower|girl|mother|mom/i,'For Him':/golf|guitar|man |men |sports/i,Jewelry:/birth|flower|bracelet|keychain/i,'Home & Living':/blanket|light|ornament/i,Wedding:/wedding|flower|bridesmaid/i,Birthday:/birthday/i,Marsupilami:/animal|cartoon/i};
function productsFor(category){if(category==='Wishlist')return DATA.products.filter(p=>wishes.includes(p.id));if(category==='New Arrivals')return DATA.products.slice(28);if(category==='Best Sellers')return DATA.products.slice(0,12);return matches[category]?DATA.products.filter(p=>matches[category].test(p.name)):DATA.products}
function card(p,index){return `<article class="product-card"><div class="product-image" data-product="${p.id}" tabindex="0" role="button" aria-label="Personalize ${escapeHTML(p.name)}"><img src="${p.image}" alt="${escapeHTML(p.name)}" loading="lazy"><span class="product-tag">${index%3===0?'BEST SELLER':index%3===1?'MADE FOR YOU':'PERSONALIZED'}</span><button class="heart ${wishes.includes(p.id)?'saved':''}" data-wish="${p.id}" aria-label="${wishes.includes(p.id)?'Remove from':'Add to'} wishlist" aria-pressed="${wishes.includes(p.id)}">${icon('heart')}</button><button class="quick-add" data-product="${p.id}">Personalize now +</button></div><button class="product-name" data-product="${p.id}">${escapeHTML(p.name)}</button><div class="rating">★★★★★ <span>(${17+p.id*13})</span></div><div class="product-price">${money(p.price)} <del>${money(Math.ceil(p.price*1.25))}</del></div><div class="personalize-note">Made personal, at no extra cost</div></article>`}
function renderProducts(){let list=productsFor(currentCategory);if(currentSearch)list=DATA.products.filter(p=>p.name.toLowerCase().includes(currentSearch.toLowerCase()));const sort=$('#sort').value;if(sort==='low')list=[...list].sort((a,b)=>a.price-b.price);if(sort==='high')list=[...list].sort((a,b)=>b.price-a.price);$('#catalog-title').textContent=currentSearch?`Results for “${currentSearch}”`:currentCategory==='All'?'All Personalized Gifts':currentCategory;$('#catalog-eyebrow').textContent=currentSearch?`${list.length} THOUGHTFUL FINDS`:currentCategory==='Wishlist'?'SAVED FOR SOMEONE SPECIAL':'LOVED BY YOU';$('#products').innerHTML=list.length?list.slice(0,limit).map(card).join(''):`<div class="empty-state">${icon(currentCategory==='Wishlist'?'heart':'search')}<h3>${currentCategory==='Wishlist'?'Your favorites belong here':'No gifts found just yet'}</h3><p>${currentCategory==='Wishlist'?'Tap the heart on a gift to save it for later.':'Try “flower”, “blanket”, “golf”, or “photo”.'}</p><button class="primary" data-category="All">Explore all gifts</button></div>`;$('#load-more').hidden=list.length<=limit;$('#load-more').textContent=`Discover more gifts (${Math.max(0,list.length-limit)}) →`;$$('#filters button').forEach(b=>b.classList.toggle('selected',b.dataset.category===currentCategory));$$('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.category===currentCategory));}
$('#filters').innerHTML=['Best Sellers','All','For Her','For Him','For Kids','Christmas'].map((n,i)=>`<button data-category="${n}" class="${i===0?'selected':''}">${n==='All'?'All Gifts':n}</button>`).join('');
function browse(category,search=''){currentCategory=category;currentSearch=search;limit=10;$('#search-input').value=search;renderProducts();$('#catalog').scrollIntoView({behavior:'smooth',block:'start'});$('#navigation').classList.remove('mobile-open');document.activeElement?.blur()}
renderProducts();$('#new-products').innerHTML=DATA.products.slice(28,33).map(card).join('');$('#story-images').innerHTML=[DATA.products[2],DATA.products[7]].map(p=>`<img src="${p.image}" alt="${escapeHTML(p.name)}" loading="lazy">`).join('');
$('#search-tags').innerHTML=['Christmas','Blankets','For Kids','Night Lights','Wedding'].map(n=>`<button type="button" data-category="${n}">${n}</button>`).join('');
$('#search-form').onsubmit=e=>{e.preventDefault();const q=$('#search-input').value.trim();browse('All',q)};$('#sort').onchange=renderProducts;$('#load-more').onclick=()=>{limit+=10;renderProducts()};$('#view-all').onclick=()=>browse('All');$('#new-all').onclick=()=>browse('New Arrivals');$('#story-shop').onclick=()=>browse('All');$('#wishlist').onclick=()=>browse('Wishlist');$('#menu-toggle').onclick=()=>$('#navigation').classList.toggle('mobile-open');
function openModal(content){$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('.modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};
function showProduct(id){const p=DATA.products.find(p=>p.id===id);if(!p)return;openModal(`<div class="product-detail"><div class="detail-picture"><img src="${p.image}" alt="${escapeHTML(p.name)}"><div class="name-preview" id="name-preview">Made just for you ♡</div></div><form class="detail-copy" id="personalize-form"><span class="eyebrow">A GIFT THAT TELLS THEIR STORY</span><h2>${escapeHTML(p.name)}</h2><div class="rating">★★★★★ <span>(${17+p.id*13} reviews)</span></div><div class="product-price">${money(p.price)} <del>${money(Math.ceil(p.price*1.25))}</del></div><label for="custom-name">Their name or your special message *</label><input id="custom-name" maxlength="30" placeholder="e.g. Emma" required autocomplete="off"><small>Add up to 30 characters. The label on the image previews your text.</small><label for="gift-wrap">The finishing touch</label><select id="gift-wrap"><option value="0">Standard packaging · Included</option><option value="4">Gift-ready wrapping · +$4.00</option></select><button class="primary" type="submit">Add to bag · <span id="add-price">${money(p.price)}</span></button><small>♡ Personalized just for you · 99-day returns</small><details><summary>Details & care</summary><p>A thoughtful keepsake personalized with your own message. Handle with care. Product imagery is from the reference store; this is a frontend demonstration.</p></details><details><summary>Shipping & returns</summary><p>This demo does not place real orders or arrange delivery. Connect your store backend to enable live shipping and fulfillment.</p></details></form></div>`);$('#custom-name').oninput=e=>$('#name-preview').textContent=e.target.value||'Made just for you ♡';$('#gift-wrap').onchange=e=>$('#add-price').textContent=money(p.price+Number(e.target.value));$('#personalize-form').onsubmit=e=>{e.preventDefault();const name=$('#custom-name').value.trim();if(!name)return $('#custom-name').focus();const wrapping=Number($('#gift-wrap').value),key=id+'|'+name+'|'+wrapping,existing=cart.find(x=>x.key===key);if(existing)existing.qty++;else cart.push({id,key,name,wrapping,qty:1});persist();closeModal();openCart();toast('A little something special, added to your bag ♡')}}
function toggleWish(id){wishes=wishes.includes(id)?wishes.filter(x=>x!==id):[...wishes,id];persist();renderProducts();$('#new-products').innerHTML=DATA.products.slice(28,33).map(card).join('');toast(wishes.includes(id)?'Saved to your wishlist ♡':'Removed from your wishlist')}
function openCart(){renderCart();$('#overlay').classList.add('open');$('#drawer').classList.add('open');document.body.classList.add('lock');$('#drawer .close').focus()}
function closeCart(){$('#overlay').classList.remove('open');$('#drawer').classList.remove('open');document.body.classList.remove('lock');$('#bag').focus()}
$('#bag').onclick=openCart;$('.drawer .close').onclick=closeCart;$('#overlay').onclick=closeCart;
function renderCart(){if(!cart.length){$('#cart-items').innerHTML=`<div class="empty-state">${icon('bag')}<h3>A little empty. Full of possibilities.</h3><p>Find something that says “I thought of you.”</p><button class="primary" id="cart-explore">Find your perfect gift →</button></div>`;$('#cart-footer').innerHTML='';$('#cart-explore').onclick=()=>{closeCart();browse('All')};return}let subtotal=0;$('#cart-items').innerHTML=cart.map((item,index)=>{const p=DATA.products[item.id];subtotal+=(p.price+item.wrapping)*item.qty;return `<div class="cart-item"><img src="${p.image}" alt="${escapeHTML(p.name)}"><div><h4>${escapeHTML(p.name)}</h4><small>Personalization: ${escapeHTML(item.name)}${item.wrapping?' · Gift wrapped':''}</small><div class="price-row"><div class="qty"><button data-qty="${index}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${item.qty}</span><button data-qty="${index}" data-delta="1" aria-label="Increase quantity">+</button></div><strong>${money((p.price+item.wrapping)*item.qty)}</strong></div><button class="remove" data-remove="${index}">Remove</button></div></div>`}).join('');$('#cart-footer').innerHTML=`<div class="subtotal"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><button class="primary cart-checkout" id="checkout">Review your order →</button><p>Shipping calculated at checkout.<br>This is a demo store. No payment will be collected.</p>`;$('#checkout').onclick=()=>{closeCart();openModal(`<div class="simple-modal"><span class="eyebrow">YOUR THOUGHTFUL SELECTION</span><h2>A little joy is in the bag.</h2><p>${cart.reduce((n,p)=>n+p.qty,0)} personalized gifts · Subtotal <strong>${money(subtotal)}</strong></p><p>Your selections are saved on this device. This storefront is a frontend recreation; payment, live inventory, and delivery are not connected.</p><button class="primary" id="keep-shopping">Keep finding something special →</button></div>`);$('#keep-shopping').onclick=()=>{closeModal();browse('All')}}}
document.addEventListener('click',e=>{const wish=e.target.closest('[data-wish]');if(wish){e.stopPropagation();toggleWish(+wish.dataset.wish);return}const product=e.target.closest('[data-product]');if(product){showProduct(+product.dataset.product);return}const category=e.target.closest('[data-category]');if(category){browse(category.dataset.category);return}const qty=e.target.closest('[data-qty]');if(qty){const i=+qty.dataset.qty;cart[i].qty=Math.max(1,cart[i].qty+Number(qty.dataset.delta));persist();renderCart();return}const remove=e.target.closest('[data-remove]');if(remove){cart.splice(+remove.dataset.remove,1);persist();renderCart();return}const info=e.target.closest('[data-info]');if(info)showInfo(info.dataset.info)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#drawer').classList.contains('open'))closeCart();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-image')){e.preventDefault();showProduct(+e.target.dataset.product)}});
$('#account').onclick=()=>{const name=saved('callie-profile','');openModal(`<form class="simple-modal" id="profile-form"><span class="eyebrow">YOUR LITTLE CORNER OF CALLIE</span><h2>${name?'Hello, '+escapeHTML(name)+' ♡':'Make yourself at home.'}</h2><p>Keep your gift ideas, wishlist, and shopping bag together on this device.</p><label for="profile-name">What should we call you?</label><input id="profile-name" required maxlength="40" value="${escapeHTML(name)}" placeholder="Your first name"><button class="primary">Save my name</button><p style="font-size:10px">Local demo profile · No account or password required.</p></form>`);$('#profile-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('callie-profile',JSON.stringify($('#profile-name').value.trim()));closeModal();toast('Your name is saved on this device. Welcome ♡')}};
$('#locale').onclick=()=>{openModal(`<div class="simple-modal"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>Where are you gifting?</h2><p>Choose your display currency.</p><div class="country-list">${['🇺🇸 USD','🇨🇦 CAD','🇬🇧 GBP','🇦🇺 AUD','🇪🇺 EUR','🇨🇳 CNY'].map(c=>`<button data-currency="${c}">${c}</button>`).join('')}</div><p style="font-size:10px">Product prices in this recreation remain in USD.</p></div>`);$$('[data-currency]').forEach(b=>b.onclick=()=>{toast(`${b.dataset.currency} selected. Demo product prices are shown in USD.`);closeModal()})};
function offer(){openModal(`<form class="simple-modal" id="offer-form"><span class="eyebrow">A LITTLE WELCOME GIFT</span><h2>Something special<br>starts with you.</h2><p>Enjoy 10% off your first order with code <strong>HELLOCALLIE</strong>.</p><label for="offer-email">Your email address</label><input id="offer-email" type="email" required placeholder="you@example.com"><button class="primary">Save my welcome offer →</button><p style="font-size:10px">Demo only. Your email is saved locally and is not sent to any service.</p></form>`);$('#offer-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('callie-welcome',JSON.stringify({email:$('#offer-email').value,code:'HELLOCALLIE'}));closeModal();toast('Welcome offer saved: HELLOCALLIE · 10% off')}}$('#offer').onclick=offer;
$('#newsletter-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('callie-newsletter',e.target.querySelector('input').value);toast('Email saved on this device. Demo signup complete ♡');e.target.reset()};
const infos={'Our Story':'Callie celebrates the people and moments that make life meaningful. Add a name, a memory, or a message to turn an everyday object into a thoughtful keepsake.','Why Callie':'Personalized gifts, thoughtful details, and ideas for every occasion. Browse the collections and make something uniquely theirs.','Customer Reviews':'Product rating counts in this recreation are sample data. Explore the original Callie website for verified customer reviews.','Gift Inspiration':'For the book lover, try a personalized bookmark. For a cozy night in, choose a custom blanket. For a little everyday joy, discover birth flower keepsakes.','Shipping & Delivery':'This is a frontend recreation. Shipping rates, delivery estimates, and real order tracking require a connected commerce backend.','Returns & Exchanges':'The reference store highlights 99-day returns. This demo does not process purchases or return requests.','Frequently Asked Questions':'How do I personalize a gift? Open a product, enter a name or message, then add it to your bag. Can I save favorites? Tap the heart on any product. Are these real orders? This is a frontend demo; payment and fulfillment are not connected.','Privacy Policy':'This demo saves your shopping bag, favorites, and optional profile or email in your browser’s local storage. No information is submitted to a backend. Clear your browser site data to remove it.','Terms of Service':'This independent frontend recreation is provided for design and interaction preview. It is not the official Callie store and does not accept real orders.','Social Community':'This demo does not connect to social networks. Visit the official Callie website for its social channels.'};
function showInfo(title){if(title==='Contact Us')return contact();openModal(`<div class="simple-modal"><span class="eyebrow">A LITTLE MORE ABOUT CALLIE</span><h2>${escapeHTML(title)}</h2><p>${escapeHTML(infos[title]||'Discover thoughtful, personalized gifts for every occasion.')}</p><button class="primary" id="info-close">Keep exploring →</button></div>`);$('#info-close').onclick=closeModal}
function contact(){openModal(`<form class="simple-modal" id="contact-form"><span class="eyebrow">WE'RE HERE FOR YOU</span><h2>A little help?</h2><p>Explore answers about personalization, your shopping bag, and this demo.</p><details><summary>How do I customize a gift?</summary><p>Open a product and add your own name or message. You can also choose gift wrapping.</p></details><label for="contact-email">Your email</label><input id="contact-email" type="email" required placeholder="you@example.com"><label for="contact-message">How can we help?</label><textarea id="contact-message" required placeholder="Tell us a little more…"></textarea><button class="primary">Save support request</button><p style="font-size:10px">Demo: your request is saved on this device. It is not sent to Callie.</p></form>`);$('#contact-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('callie-support',JSON.stringify({email:$('#contact-email').value,message:$('#contact-message').value}));closeModal();toast('Your demo support request was saved locally.')}}$('#support').onclick=contact;
persist();
